function demoMain(idx,label){
  var srcs=["function add(a,b){ return a + b; }","var x = 1; var y = 2;","if (a) { b(); } else { c(); }"];
  var s=srcs[idx%srcs.length];
  var min=s.replace(/\s+/g," ").replace(/\s*([{}();,])\s*/g,"$1");
  return "["+label+"] "+s.length+" chars -> "+min.length+" chars: '"+min+"'";
}

